def atomic_json(path,value):
    old=path.read_bytes();temp=path.with_suffix(path.suffix+'.native_result.pending')
    with temp.open('x',encoding='utf8',newline='\n') as f:json.dump(cast(value),f,ensure_ascii=False,indent=2,allow_nan=False);f.write('\n')
    assert path.read_bytes()==old;temp.replace(path)
